@layer reset, components;

@layer reset {
  :where(h1, h2, h3) {
    margin: 0;
  }
}

@layer components {
  :is(.card, .panel) > h2 {
    margin-bottom: 12px;
  }
}

:root {
  --brand: #ff5a36;
  --radius: 12px;
}

.button {
  background-color: var(--brand);
  border-radius: var(--radius);
}

:root {
  --accent: #3377cc;
}

.card {
  --accent: #ff5a36;
}

.card__tag {
  color: var(--accent);
}

:root {
  --surface: #ffffff;
  --text: #1a1a1a;
}

@media (prefers-color-scheme: dark) {
  :root {
    --surface: #111111;
    --text: #f5f5f5;
  }
}

body {
  color: var(--text, #1a1a1a);
  background-color: var(--surface);
}

:root {
  --gutter: 16px;
}

.layout {
  display: flex;
  padding: var(--gutter);
  gap: calc(var(--gutter) / 2);
}

.button {
  background-color: #ff5a36;
  transition: background-color 200ms ease;
}

.button:hover {
  background-color: #d94a2b;
}

.card {
  transition: transform 200ms ease;
}

.card:hover {
  transform: translateY(-4px) scale(1.02);
}

@keyframes pulse {
  from {
    opacity: 1;
  }

  to {
    opacity: 0.4;
  }
}

.dot {
  animation: pulse 1.2s ease-in-out infinite alternate;
}

@keyframes fade-up {
  from {
    opacity: 0;
    transform: translateY(8px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.toast {
  animation: fade-up 240ms ease-out 120ms both;
}

.spinner {
  animation: spin 900ms linear infinite;
}

@keyframes spin {
  to {
    transform: rotate(1turn);
  }
}

@media (prefers-reduced-motion: reduce) {
  .spinner {
    animation: none;
  }
}

:root {
  --card-bg: #ffffff;
  --card-ink: #1a1a1a;
  --accent: #ff5a36;
}

.card {
  background-color: var(--card-bg);
  color: var(--card-ink);
  border: 1px solid transparent;
  border-radius: 16px;
  padding: 24px;
  transition: transform 200ms ease, border-color 200ms ease;
}

.card:hover {
  transform: translateY(-6px);
  border-color: var(--accent);
}

.card__badge {
  color: var(--accent);
  animation: pop 240ms ease-out both;
}

@keyframes pop {
  from {
    transform: scale(0.8);
  }

  to {
    transform: scale(1);
  }
}
